'use strict';
(()=>{
const url=location.origin+'/api/mcp',status=document.getElementById('copy-status');
for(const id of ['mcp-url','codex-config','claude-code-command']){const el=document.getElementById(id);if(el)el.textContent=el.textContent.replace('https://www.reposhelf.co.uk/api/mcp',url)}
document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById(button.dataset.copy).textContent);status.textContent='Copied.'}catch{status.textContent='Copy was unavailable. Select the text above and copy it manually.'}}));
const $=q=>document.querySelector(q);let identity=null,busy=false;
const KEYS='/api/auth?action=mcp-keys',keyDate=v=>v?new Date(v).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'never';
async function loadKeys(){const box=$('#connector-keys');box.hidden=!identity;if(!identity)return;$('#key-reveal').hidden=true;$('#new-key').textContent='';const owner=identity;try{const data=await RepoAccount.request(KEYS);if(owner!==identity)return;const list=$('#key-list');list.replaceChildren();for(const k of data.keys||[]){const li=document.createElement('li'),text=document.createElement('span'),b=document.createElement('button');text.textContent=`${k.label} · ${k.key_prefix}… · created ${keyDate(k.created_at)} · last used ${keyDate(k.last_used_at)}`;b.type='button';b.className='button outline';b.textContent='Revoke';b.setAttribute('aria-label','Revoke key '+k.label);b.onclick=async()=>{b.disabled=true;try{await RepoAccount.request(KEYS,{method:'DELETE',body:JSON.stringify({id:k.id})});$('#key-status').textContent='Key revoked. Assistants using it lose access immediately.';await loadKeys()}catch(e){b.disabled=false;$('#key-status').textContent=e.message}};li.append(text,b);list.append(li)}if(!(data.keys||[]).length){const li=document.createElement('li');li.textContent='You have no connector keys yet.';list.append(li)}}catch(e){$('#key-status').textContent=e.message}}
$('#key-form').onsubmit=async e=>{e.preventDefault();if(busy||!identity)return;busy=true;$('#key-create').disabled=true;$('#key-status').textContent='';try{const made=await RepoAccount.request(KEYS,{method:'POST',body:JSON.stringify({label:$('#key-label').value})});$('#key-label').value='';await loadKeys();$('#new-key').textContent=made.key;$('#key-reveal').hidden=false;$('#key-status').textContent='Key created.'}catch(err){$('#key-status').textContent=err.message}finally{busy=false;$('#key-create').disabled=false}};
$('#copy-new-key').onclick=async()=>{try{await navigator.clipboard.writeText($('#new-key').textContent);$('#key-status').textContent='Key copied.'}catch{$('#key-status').textContent='Copy was unavailable. Select the key and copy it manually.'}};

const gate=()=>{const A=window.RepoAccount;if(!A||!A.ready)return;const id=A.user?.id||null;$('#connect-gate').hidden=Boolean(id);if(id===identity)return;identity=id;void loadKeys()};
window.addEventListener('reposhelf-account',gate);gate();
})();